using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

public class ReportController : Controller
{
    /// <summary>
    /// Replaces btnExport_Click.
    /// Response.End() is gone — just return a result object.
    /// The framework handles flushing and closing the response.
    /// </summary>
    [HttpPost]
    public IActionResult Export()
    {
        var data = GenerateReport();

        // FileContentResult sets Content-Type, Content-Disposition,
        // and writes the body — no manual Response.Clear/Write/End.
        return File(
            System.Text.Encoding.UTF8.GetBytes(data),
            "text/csv",
            "report.csv");
    }

    /// <summary>
    /// Replaces btnRedirect_Click.
    /// Response.Redirect(url, true) called Thread.Abort to stop execution.
    /// In ASP.NET Core, returning RedirectResult ends the action naturally.
    /// No ThreadAbortException exists — remove all catch blocks for it.
    /// </summary>
    [HttpPost]
    public IActionResult ProcessAndRedirect()
    {
        if (!User.Identity?.IsAuthenticated ?? true)
        {
            return Redirect("/login"); // returns immediately — no abort needed
        }

        try
        {
            ProcessRequest();
            return Redirect("/success");
        }
        // ThreadAbortException catch is REMOVED — it doesn't exist in .NET 8.
        // OperationCanceledException replaces it if you need cancellation awareness.
        catch (Exception ex)
        {
            LogError(ex);
            return Redirect("/error");
        }
    }

    private string GenerateReport() => "col1,col2\nval1,val2";
    private void ProcessRequest() { /* business logic */ }
    private void LogError(Exception ex) { /* logging */ }
}
